const config = $input.first().json;
if (typeof config.api_base_url !== 'string' || !/^https:\/\/[^\s/]+(?:\/[^\s]*)?$/.test(config.api_base_url) || config.api_base_url.includes('.invalid')) throw new Error('Set api_base_url to your reachable HTTPS scanner URL; n8n Cloud cannot reach your localhost.');
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!uuid.test(config.project_id)) throw new Error('Set project_id to a real scanner project UUID.');
if (config.existing_run_id && !uuid.test(config.existing_run_id)) throw new Error('existing_run_id must be empty or a run UUID.');
if (!(config.poll_seconds >= 5 && config.poll_seconds <= 300) || !(config.max_poll_seconds >= config.poll_seconds && config.max_poll_seconds <= 86400)) throw new Error('Choose a 5–300 second poll interval and a bounded polling deadline.');
if (!Number.isInteger(config.review_limit) || config.review_limit < 1 || config.review_limit > 25 || !Number.isInteger(config.review_offset) || config.review_offset < 0) throw new Error('review_limit must be 1–25 and review_offset a nonnegative integer.');
if (typeof config.ai_enabled !== 'boolean') throw new Error('ai_enabled must be a boolean.');
if (typeof config.review_prompt !== 'string' || !config.review_prompt.trim() || config.review_prompt.length > 12000) throw new Error('review_prompt must contain 1–12000 characters.');
return [{ json: config }];

const run = $input.first().json;
if (!run.id || typeof run.status !== 'string') throw new Error('Scanner did not return a run object with id and status.');
const config = $('Configure monitor').first().json;
return [{ json: { run_id: run.id, project_id: config.project_id, deadline_ms: Date.now() + Number(config.max_poll_seconds) * 1000 } }];

const run = $input.first().json;
const initial = $('Initialize polling').first().json;
if (run.id !== initial.run_id || run.project_id !== initial.project_id || !['running', 'completed', 'partial', 'failed', 'cancelled'].includes(run.status)) throw new Error('Unexpected scanner run/project/status response. Check existing_run_id belongs to the configured project.');
const timedOut = run.status === 'running' && Date.now() >= initial.deadline_ms;
return [{ json: { run_id: run.id, status: run.status, keep_waiting: run.status === 'running' && !timedOut, usable: ['completed', 'partial'].includes(run.status), error: run.status === 'cancelled' ? 'The scan was stopped. Previous accepted observations were preserved; this workflow will not send images for AI review.' : timedOut ? 'Polling deadline reached. The scanner continues independently. Set existing_run_id to this run UUID to resume: ' + run.id : run.error || 'Scanner run failed.' } }];

const body = $input.first().json;
if (!Array.isArray(body.items)) throw new Error('Review API did not return an items array.');
const runId = body.run_id || $('Initialize polling').first().json.run_id;
const hasMore = body.next_offset !== null && body.next_offset !== undefined;
const items = body.items.filter(pair => ['new', 'changed'].includes(pair.visual_status) && pair.current && pair.current.status === 'captured' && !(pair.current.analysis && pair.current.analysis.reviewed_at)).map(pair => ({ ...pair, run_id: runId }));
return [{ json: { run_id: runId, items, has_items: items.length > 0, changed_pairs: items.length, has_more: hasMore, next_offset: hasMore ? body.next_offset : null, pagination_warning: hasMore ? 'More changed captures remain. Reuse this run ID and set review_offset to next_offset; this page is not the complete review.' : null, review_status: 'ready_for_review' } }];

const body = $input.first().json;
if (!Array.isArray(body.items) || body.items.length !== 1) throw new Error('Expected exactly one changed capture pair with inline images.');
const pair = body.items[0];
const requested = $('Process one image pair').item.json;
if ((body.run_id && body.run_id !== requested.run_id) || pair.domain !== requested.domain || pair.scheme !== requested.scheme) throw new Error('Image response does not match the requested run/domain/scheme.');
if (!['new', 'changed'].includes(pair.visual_status)) throw new Error('An unchanged capture reached the image review branch.');
const validImage = value => typeof value === 'string' && /^data:image\/(?:png|jpeg);base64,[A-Za-z0-9+/=\r\n]+$/.test(value);
if (!pair.current || !validImage(pair.current.image_data_url)) throw new Error('Current image bytes are missing or invalid. Private scanner URLs cannot replace inline image data.');
const images = [];
if (pair.previous && validImage(pair.previous.image_data_url)) images.push({ label: 'PREVIOUS capture of the same candidate and scheme', url: pair.previous.image_data_url });
images.push({ label: 'CURRENT capture of the candidate', url: pair.current.image_data_url });
for (const reference of (pair.references || []).slice(0, 1)) {
  if (validImage(reference.image_data_url)) images.push({ label: 'OWNED REFERENCE screenshot, source ' + (reference.url || 'configured original domain'), url: reference.image_data_url });
}
const hasPrevious = images.some(image => image.label.startsWith('PREVIOUS'));
const instruction = $('Configure monitor').first().json.review_prompt;
const binary = {};
const imageOrder = [];
for (const [index, image] of images.entries()) {
  const match = image.url.match(/^data:(image\/(?:png|jpeg));base64,([A-Za-z0-9+/=\r\n]+)$/);
  const field = 'image_' + (index + 1);
  const extension = match[1] === 'image/png' ? 'png' : 'jpg';
  binary[field] = { data: match[2].replace(/\s/g, ''), mimeType: match[1], fileName: field + '.' + extension, fileExtension: extension };
  imageOrder.push('Image ' + (index + 1) + ': ' + image.label);
}
const context = 'Candidate context: ' + JSON.stringify({ domain: pair.domain, scheme: pair.scheme, requested_url: pair.current.url, visual_status: pair.visual_status, has_previous_capture: hasPrevious });
const prompt = instruction + '\n\n' + context + '\n\nImages are attached in this exact order:\n' + imageOrder.join('\n');
return [{ json: { run_id: body.run_id || $('Initialize polling').first().json.run_id, domain: pair.domain, scheme: pair.scheme, visual_status: pair.visual_status, has_previous: hasPrevious, image_fields: Object.keys(binary).join(','), image_count: images.length, prompt }, binary, pairedItem: { item: 0 } }];

const items = $input.all().map(item => item.json);
const manifest = $('Validate changed manifest').first().json;
const sent = items.reduce((total, item) => total + (item.ai_requests_sent || 0), 0);
const saved = items.reduce((total, item) => total + (item.assessments_saved || 0), 0);
return [{ json: { run_id: manifest.run_id, processed_pairs: items.length, ai_requests_sent: sent, assessments_saved: saved, model: 'gpt-4o-mini', review_status: $('Configure monitor').first().json.ai_enabled ? 'ai_review_page_saved' : 'ai_disabled', has_more: manifest.has_more, next_offset: manifest.next_offset, pagination_warning: manifest.pagination_warning, detail: manifest.has_more ? 'More changed captures remain; this is one review page, not the complete run.' : 'This page finished. AI results, if enabled, are assessments for human review.' } }];

const response = $input.first().json;
const request = $('Build gpt-4o-mini request').item.json;
if (response.error) throw new Error('OpenAI returned an error; no AI assessment was saved.');
if (typeof response.model !== 'string' || !/^gpt-4o-mini(?:-\d{4}-\d{2}-\d{2})?$/.test(response.model)) throw new Error('Unexpected model in response; no substitution is allowed.');
if (response.status !== 'completed' || !Array.isArray(response.output)) throw new Error('OpenAI response was incomplete or malformed; no assessment was saved.');
const messages = response.output.filter(item => item && item.type === 'message');
if (messages.length !== 1 || response.output.some(item => !item || item.type !== 'message')) throw new Error('Expected exactly one OpenAI message and no tool output.');
const message = messages[0];
if (message.role !== 'assistant' || message.status !== 'completed' || !Array.isArray(message.content) || message.content.length !== 1 || message.content[0].type !== 'output_text' || typeof message.content[0].text !== 'string') throw new Error('OpenAI response was refused or did not contain one text assessment.');
const assessmentText = message.content[0].text;
let result;
try { result = JSON.parse(assessmentText); } catch (_) { throw new Error('OpenAI returned invalid JSON; no assessment was saved.'); }
if (!result || Array.isArray(result) || typeof result !== 'object') throw new Error('AI assessment must be a JSON object.');
if (typeof result.summary !== 'string' || !result.summary.trim() || result.summary.length > 4000) throw new Error('AI summary must contain 1–4000 characters.');
if (!['low', 'medium', 'high', 'uncertain'].includes(result.risk)) throw new Error('AI risk value is invalid.');
if (result.changed !== null && typeof result.changed !== 'boolean') throw new Error('AI changed value must be boolean or null.');
if (!request.has_previous && result.changed !== null) throw new Error('A first capture cannot claim a change from an absent visual baseline.');
if (typeof result.confidence !== 'number' || !Number.isFinite(result.confidence) || result.confidence < 0 || result.confidence > 1) throw new Error('AI confidence must be a finite number from 0 to 1.');
return [{ json: { run_id: request.run_id, domain: request.domain, scheme: request.scheme, visual_status: request.visual_status, assessment: { domain: request.domain, scheme: request.scheme, provider: 'OpenAI', model: 'gpt-4o-mini', summary: result.summary.trim(), risk: result.risk, changed: result.changed, confidence: result.confidence } } }];
